package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown when a submitted owner email is present but is not a syntactically valid address.
 * Carries the offending (raw) value so it can be reported to the client.
 */
public class InvalidEmailException extends RuntimeException {

    private final String rejectedValue;

    public InvalidEmailException(String rejectedValue) {
        super("Email must be a syntactically valid address: " + rejectedValue);
        this.rejectedValue = rejectedValue;
    }

    public String getRejectedValue() {
        return this.rejectedValue;
    }
}

