40	import org.springframework.samples.petclinic.model.Pet;
41	import org.springframework.samples.petclinic.model.Visit;
42	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
43	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
44	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
45	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
46	import org.springframework.samples.petclinic.rest.advice.HouseholdDuplicateException;
47	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
48	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
49	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
50	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
51	import org.springframework.samples.petclinic.rest.api.OwnersApi;
52	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
53	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
54	import org.springframework.samples.petclinic.rest.dto.PetDto;
55	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
56	import org.springframework.samples.petclinic.rest.dto.VisitDto;
57	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
58	import org.springframework.samples.petclinic.service.ClinicService;
59	import org.springframework.security.access.prepost.PreAuthorize;
60	import org.springframework.web.bind.annotation.CrossOrigin;
61	import org.springframework.web.bind.annotation.RequestMapping;
62	import org.springframework.web.bind.annotation.RestController;
63	import org.springframework.web.util.UriComponentsBuilder;
64	
65	import jakarta.transaction.Transactional;
66	
67	/**
68	 * @author Vitaliy Fedoriv
69	 */
70	
71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    /**
77	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
78	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
79	     */
80	    private static final Pattern EMAIL_PATTERN =
81	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
82	
83	    /**
84	     * Dedicated audit logger. On a successful owner create an audit line is emitted carrying the
85	     * new owner's id, customerCode, registrationDate and membershipLevel.
86	     */
87	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
88	
89	    /**
90	     * Common street-type abbreviations expanded during address normalization, keyed by the
91	     * upper-cased abbreviation.
92	     */
93	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
94	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
95	
96	    /**
97	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
98	     * city already holds this many owners.
99	     */
100	    private static final int CITY_CAPACITY = 50;
101	
102	    /**
103	     * Maximum number of owners that may be created on a single day. A create is rejected once this
104	     * many owners already carry the current day as their {@code registrationDate}.
105	     */
106	    private static final int DAILY_OWNER_LIMIT = 100;
107	
108	    private final ClinicService clinicService;
109	
110	    private final OwnerMapper ownerMapper;
111	
112	    private final PetMapper petMapper;
113	
114	    private final VisitMapper visitMapper;
115	
116	    public OwnerRestControllerV1(ClinicService clinicService,
117	                                 OwnerMapper ownerMapper,
118	                                 PetMapper petMapper,
119	                                 VisitMapper visitMapper) {
120	        this.clinicService = clinicService;
121	        this.ownerMapper = ownerMapper;
122	        this.petMapper = petMapper;
123	        this.visitMapper = visitMapper;
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
129	        Collection<Owner> owners;
130	        if (lastName != null) {
131	            owners = this.clinicService.findOwnerByLastName(lastName);
132	        } else {
133	            owners = this.clinicService.findAllOwners();
134	        }
135	        if (owners.isEmpty()) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
144	        Owner owner = this.clinicService.findOwnerById(ownerId);
145	        if (owner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
154	        validateRequiredFields(ownerFieldsDto);
155	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
156	        HttpHeaders headers = new HttpHeaders();
157	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
158	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
159	        rejectFutureRegistrationDate(owner.getRegistrationDate());
160	        LocalDate effectiveDate = owner.getRegistrationDate() == null
161	            ? LocalDate.now()
162	            : owner.getRegistrationDate();
163	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
164	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
165	        rejectWhenCityAtCapacity(owner.getCity());
166	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
167	        applyHousehold(owner, sharesHousehold);
168	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
169	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
170	        rejectDuplicateIdentity(owner);
171	        owner.setCustomerCode(customerCode(owner));
172	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
173	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
174	        flagPossibleDuplicate(owner, sharesHousehold);
175	        this.clinicService.saveOwner(owner);
176	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
177	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
178	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
179	            ownerDto.getMembershipLevel());
180	        headers.setLocation(UriComponentsBuilder.newInstance()
181	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
182	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
183	    }
184	
185	    /**
186	     * Builds the owner's customer code, formatted {@code <REGION>-<HASH8>} where REGION is the region
187	     * code derived from the owner's postcode (falling back to the city-to-region table, then
188	     * {@code UNKNOWN}) and HASH8 is the first 8 upper-cased hex characters of the SHA-256 of the
189	     * owner's normalized telephone concatenated with its last name (e.g. {@code NSW-1A2B3C4D}). The
190	     * code is a pure function of the owner's region and identity, carrying no sequence number.
191	     *
192	     * @param owner the owner being created, with its normalized telephone already applied
193	     * @return the assigned customer code
194	     */
195	    private String customerCode(Owner owner) {
196	        return regionCode(owner) + "-" + identityHash8(owner.getTelephone(), owner.getLastName());
197	    }
198	
199	    /**
200	     * Derives the region code embedded in an owner's customer code, preferring the postcode: a
201	     * 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
202	     * QLD 4000-4099) yields that region. Otherwise the city-to-region table (Sydney->NSW,
203	     * Melbourne->VIC, Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither the
204	     * postcode nor the city identifies a region.
205	     *
206	     * @param owner the owner being created
207	     * @return the derived region code, never {@code null}
208	     */
209	    private String regionCode(Owner owner) {
210	        String fromPostcode = regionFromPostcode(owner.getPostcode());
211	        if (fromPostcode != null) {
212	            return fromPostcode;
213	        }
214	        String fromCity = region(owner.getCity());
215	        return fromCity == null ? "UNKNOWN" : fromCity;
216	    }
217	
218	    /**
219	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when the
220	     * postcode is absent, not 4 digits, or in no known range.
221	     *
222	     * @param postcode the owner's postcode, may be {@code null}
223	     * @return the region code, or {@code null} when no known range contains the postcode
224	     */
225	    private String regionFromPostcode(String postcode) {
226	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
227	            return null;
228	        }
229	        int value = Integer.parseInt(postcode);
230	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
231	            int[] range = entry.getValue();
232	            if (value >= range[0] && value <= range[1]) {
233	                return entry.getKey();
234	            }
235	        }
236	        return null;
237	    }
238	
239	    /**
240	     * Computes the identity hash embedded in an owner's customer code: the first 8 upper-cased hex
241	     * characters of the SHA-256 of the owner's normalized telephone concatenated with its last name.
242	     *
243	     * @param telephone the owner's normalized (E.164) telephone
244	     * @param lastName  the owner's last name
245	     * @return the 8-character upper-cased hex hash
246	     */
247	    private String identityHash8(String telephone, String lastName) {
248	        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
249	        try {
250	            byte[] digest = MessageDigest.getInstance("SHA-256")
251	                .digest(input.getBytes(StandardCharsets.UTF_8));
252	            StringBuilder hex = new StringBuilder(digest.length * 2);
253	            for (byte b : digest) {
254	                hex.append(String.format("%02x", b));
255	            }
256	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
257	        } catch (NoSuchAlgorithmException ex) {
258	            throw new IllegalStateException("SHA-256 not available", ex);
259	        }
260	    }
261	
262	    /**
263	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
264	     * last two digits of the registrationDate year, zero-padded (e.g. {@code NSW-1A2B3C4D-M26}).
265	     *
266	     * @param customerCode     the owner's assigned customer code
267	     * @param registrationDate the owner's registration date
268	     * @return the assigned membership number
269	     */
270	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
271	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
272	    }
273	
274	    /**
275	     * Counts the existing owners that already share the given firstName and lastName, compared
276	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
277	     * the owners that pre-existed this create.
278	     *
279	     * @param firstName the new owner's first name
280	     * @param lastName  the new owner's last name
281	     * @return the number of existing namesakes
282	     */
283	    private int countNamesakes(String firstName, String lastName) {
284	        return (int) this.clinicService.findAllOwners().stream()
285	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
286	                && equalsIgnoreCase(existing.getLastName(), lastName))
287	            .count();
288	    }
289	
290	    /**
291	     * Flags an owner as a possible (soft) duplicate. Although it is not a hard duplicate (its whole
292	     * {@link #identityKey(Owner) identityKey} is unique, so the create was not rejected), it may
293	     * still resemble an existing owner: when it shares an existing owner's lastName (compared
294	     * case-insensitively) and postcode while carrying a different telephone, the owner is flagged
295	     * with {@code possibleDuplicate=true} and {@code possibleDuplicateOf} set to that existing
296	     * owner's id. When no such owner exists the flag is set to {@code false} and no match id is
297	     * recorded. An owner with no postcode can never soft-match and is always {@code false}.
298	     *
299	     * <p>A declared household member (created with {@code sharesHousehold=true}) is never a suspected
300	     * duplicate: its match with an existing household member is a deliberate, declared one, so it is
301	     * always flagged {@code false}.
302	     *
303	     * @param owner           the owner being created, with its normalized telephone already applied
304	     * @param sharesHousehold whether the request declared it shares a household; a declared member is
305	     *                        never flagged as a possible duplicate
306	     */
307	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
308	        Owner match = sharesHousehold ? null : findPossibleDuplicate(owner);
309	        if (match != null) {
310	            owner.setPossibleDuplicate(true);
311	            owner.setPossibleDuplicateOf(match.getId());
312	        } else {
313	            owner.setPossibleDuplicate(false);
314	            owner.setPossibleDuplicateOf(null);
315	        }
316	    }
317	
318	    /**
319	     * Finds the existing owner this owner soft-matches: same lastName (case-insensitive) and same
320	     * postcode, but a different telephone. When several existing owners match, the one with the
321	     * lowest id is chosen so the result is deterministic. Returns {@code null} when the owner has no
322	     * postcode or no such existing owner exists.
323	     *
324	     * @param owner the owner being created
325	     * @return the matching existing owner, or {@code null} when there is no soft-match
326	     */
327	    private Owner findPossibleDuplicate(Owner owner) {
328	        if (isBlank(owner.getPostcode())) {
329	            return null;
330	        }
331	        return this.clinicService.findAllOwners().stream()
332	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
333	                && owner.getPostcode().equals(existing.getPostcode())
334	                && !equalsIgnoreCase(existing.getTelephone(), owner.getTelephone()))
335	            .min(Comparator.comparing(Owner::getId))
336	            .orElse(null);
337	    }
338	
339	    /**
340	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
341	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
342	     * customer-code sequence is derived.
343	     *
344	     * @param city the new owner's city
345	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
346	     */
347	    private void rejectWhenCityAtCapacity(String city) {
348	        long count = this.clinicService.findAllOwners().stream()
349	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
350	            .count();
351	        if (count >= CITY_CAPACITY) {
352	            throw new CityAtCapacityException(city);
353	        }
354	    }
355	
356	    /**
357	     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners already carry the
358	     * given business day as their {@code registrationDate}. The day is the owner's adjusted,
359	     * business-day registration date, so the limit is enforced per business day and weekend
360	     * requests count against the Monday they roll forward to.
361	     *
362	     * @param registrationDate the owner's adjusted (business-day) registration date
363	     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry that
364	     *                                  registration date
365	     */
366	    private void rejectWhenDailyLimitReached(LocalDate registrationDate) {
367	        long count = this.clinicService.findAllOwners().stream()
368	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
369	            .count();
370	        if (count >= DAILY_OWNER_LIMIT) {
371	            throw new DailyOwnerLimitException(registrationDate);
372	        }
373	    }
374	
375	    /**
376	     * Rejects creating an owner whose supplied {@code registrationDate} lies in the future, i.e. is
377	     * later than the current server date. A {@code null} registration date is accepted (it defaults
378	     * to the server date) and today or any past date is allowed; only a future value is rejected.
379	     *
380	     * @param registrationDate the registration date supplied on the request, may be {@code null}
381	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
382	     */
383	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
384	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
385	            throw new FutureRegistrationDateException(registrationDate);
386	        }
387	    }
388	
389	    /**
390	     * Rolls a registration date forward onto a business day: when it falls on a Saturday or Sunday
391	     * it advances to the following Monday, otherwise it is returned unchanged. Applied to the
392	     * effective registration date (whether supplied in the request or defaulted to the server date)
393	     * so a weekend value never persists as an owner's {@code registrationDate}.
394	     *
395	     * @param date the effective registration date
396	     * @return the same date when it is a weekday, otherwise the next Monday
397	     */
398	    private LocalDate toBusinessDay(LocalDate date) {
399	        return switch (date.getDayOfWeek()) {
400	            case SATURDAY -> date.plusDays(2);
401	            case SUNDAY -> date.plusDays(1);
402	            default -> date;
403	        };
404	    }
405	
406	    private boolean equalsIgnoreCase(String a, String b) {
407	        return a == null ? b == null : a.equalsIgnoreCase(b);
408	    }
409	
410	    /**
411	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
412	     * offending field so the client learns about all of them at once.
413	     *
414	     * @param ownerFieldsDto the submitted owner fields
415	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
416	     *                                     missing or blank
417	     */
418	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
419	        List<String> errors = new ArrayList<>();
420	        if (isBlank(ownerFieldsDto.getFirstName())) {
421	            errors.add("firstName");
422	        }
423	        if (isBlank(ownerFieldsDto.getLastName())) {
424	            errors.add("lastName");
425	        }
426	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
427	            errors.add("address");
428	        }
429	        if (isBlank(ownerFieldsDto.getCity())) {
430	            errors.add("city");
431	        }
432	        if (isBlank(ownerFieldsDto.getTelephone())) {
433	            errors.add("telephone");
434	        }
435	        if (!errors.isEmpty()) {
436	            throw new MissingOwnerFieldsException(errors);
437	        }
438	    }
439	
440	    private boolean isBlank(String value) {
441	        return value == null || value.isBlank();
442	    }
443	
444	    /**
445	     * The fixed inclusive 4-digit postcode range allowed for each region, keyed by region code
446	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
447	     */
448	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
449	        "NSW", new int[] {2000, 2099},
450	        "VIC", new int[] {3000, 3099},
451	        "QLD", new int[] {4000, 4099});
452	
453	    /**
454	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
455	     * is optional and accepted, keeping the create contract backward-compatible. When present the
456	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
457	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
458	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
459	     *
460	     * @param postcode the raw postcode value as submitted, may be {@code null}
461	     * @param city     the owner's city, used to resolve the region whose range applies
462	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
463	     *                                  the city's region
464	     */
465	    private void validatePostcode(String postcode, String city) {
466	        if (isBlank(postcode)) {
467	            return;
468	        }
469	        if (!postcode.matches("[0-9]{4}")) {
470	            throw new InvalidPostcodeException(postcode, city);
471	        }
472	        String region = region(city);
473	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
474	        if (range != null) {
475	            int value = Integer.parseInt(postcode);
476	            if (value < range[0] || value > range[1]) {
477	                throw new InvalidPostcodeException(postcode, city);
478	            }
479	        }
480	    }
481	
482	    /**
483	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
484	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
485	     *
486	     * @param city the owner's city
487	     * @return the region code, or {@code null} when the city has no known region
488	     */
489	    private String region(String city) {
490	        if (city == null) {
491	            return null;
492	        }
493	        return switch (city) {
494	            case "Sydney" -> "NSW";
495	            case "Melbourne" -> "VIC";
496	            case "Brisbane" -> "QLD";
497	            default -> null;
498	        };
499	    }
500	
501	    /**
502	     * The number of national (subscriber) digits an E.164 number must carry for a given country
503	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
504	     * national digits and the North American Numbering Plan ('+1') requires 10.
505	     */
506	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
507	        Map.of("61", 9, "1", 10);
508	
509	    /**
510	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
511	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
512	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
513	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
514	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
515	     *
516	     * @param telephone the raw telephone value as submitted
517	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
518	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
519	     *                                   national-number length is wrong for its country code
520	     */
521	    private String normalizeTelephone(String telephone) {
522	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
523	        String nationalSignificantNumber;
524	        if (cleaned.startsWith("+")) {
525	            nationalSignificantNumber = cleaned.substring(1);
526	        } else {
527	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
528	            nationalSignificantNumber = "61" + national;
529	        }
530	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
531	            throw new InvalidTelephoneException(telephone);
532	        }
533	        validateNationalNumberLength(nationalSignificantNumber, telephone);
534	        return "+" + nationalSignificantNumber;
535	    }
536	
537	    /**
538	     * Validates the national-number length of an E.164 number against its country calling code. The
539	     * significant number is a country code immediately followed by the national digits; for each
540	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
541	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
542	     * left unchecked.
543	     *
544	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
545	     * @param rejectedValue             the raw telephone value, reported on rejection
546	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
547	     */
548	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
549	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
550	            String countryCode = rule.getKey();
551	            if (nationalSignificantNumber.startsWith(countryCode)) {
552	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
553	                if (nationalDigits != rule.getValue()) {
554	                    throw new InvalidTelephoneException(rejectedValue);
555	                }
556	                return;
557	            }
558	        }
559	    }
560	
561	    /**
562	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
563	     * value is treated as absent and returns {@code null}); when present the value must be a
564	     * syntactically valid address, and is stored and returned lower-cased.
565	     *
566	     * @param email the raw email value as submitted, may be {@code null}
567	     * @return the lower-cased email, or {@code null} when none was supplied
568	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
569	     */
570	    private String normalizeEmail(String email) {
571	        if (email == null || email.isBlank()) {
572	            return null;
573	        }
574	        String normalized = email.trim().toLowerCase();
575	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
576	            throw new InvalidEmailException(email);
577	        }
578	        return normalized;
579	    }
580	
581	    /**
582	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
583	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing owner. Because the
584	     * key is the normalized telephone, email and householdId joined together, this one check
585	     * subsumes the former separate telephone, email and household duplicate rules: only an exact
586	     * full-key match counts as a duplicate, so two members of the same household (same householdId)
587	     * with different telephones have different keys and are both allowed.
588	     *
589	     * @param owner the owner being created, with its normalized telephone, email and householdId
590	     *              already applied
591	     * @throws DuplicateIdentityException if another owner already has the same identityKey
592	     */
593	    private void rejectDuplicateIdentity(Owner owner) {
594	        String identityKey = identityKey(owner);
595	        boolean inUse = this.clinicService.findAllOwners().stream()
596	            .map(this::identityKey)
597	            .anyMatch(identityKey::equals);
598	        if (inUse) {
599	            throw new DuplicateIdentityException(identityKey);
600	        }
601	    }
602	
603	    /**
604	     * Derives an owner's {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) +
605	     * '|' + householdId}. A {@code null} email or householdId contributes an empty segment. Every
606	     * duplicate decision is made by comparing whole identityKeys.
607	     *
608	     * @param owner the owner whose identityKey to derive
609	     * @return the derived identityKey
610	     */
611	    private String identityKey(Owner owner) {
612	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
613	        String email = owner.getEmail() == null ? "" : owner.getEmail();
614	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
615	        return telephone + "|" + email + "|" + householdId;
616	    }
617	
618	    /**
619	     * Applies the household rule to an owner being created. The household is keyed on
620	     * (lastName, postcode): the owner is assigned the deterministic {@link #householdId(Owner)
621	     * householdId} derived from its normalized lastName and postcode, so owners sharing a lastName
622	     * and postcode automatically share the identifier — the link is computed, not created by a flag.
623	     *
624	     * <p>Because the household is keyed on (lastName, postcode), any existing owner that derives the
625	     * same householdId is a member of the same household, and a second owner joining it is a
626	     * household duplicate. Such a create is rejected with 409 unless the request declares
627	     * {@code sharesHousehold=true}, in which case it is allowed through as a declared household
628	     * member. The {@code sharesHousehold} directive only bypasses this duplicate block.
629	     *
630	     * @param owner           the owner being created
631	     * @param sharesHousehold whether the request declared it shares a household, bypassing the block
632	     * @throws HouseholdDuplicateException if an existing owner already shares the household and the
633	     *                                     request did not declare {@code sharesHousehold=true}
634	     */
635	    private void applyHousehold(Owner owner, boolean sharesHousehold) {
636	        String householdId = householdId(owner);
637	        owner.setHouseholdId(householdId);
638	        boolean householdExists = this.clinicService.findAllOwners().stream()
639	            .anyMatch(existing -> householdId.equals(householdId(existing)));
640	        if (householdExists && !sharesHousehold) {
641	            throw new HouseholdDuplicateException(householdId);
642	        }
643	    }
644	
645	    /**
646	     * Derives the stable, shared household identifier for an owner, formatted {@code HH-<HEX12>}
647	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the owner's normalized
648	     * lastName, a {@code '|'} separator, and its postcode. Being a pure function of (lastName,
649	     * postcode), every owner sharing a lastName and postcode derives the same value regardless of
650	     * creation order. A {@code null} postcode contributes an empty segment.
651	     *
652	     * @param owner the owner whose household identifier to derive
653	     * @return the household identifier
654	     */
655	    private String householdId(Owner owner) {
656	        String lastNameKey = toHouseholdKey(owner.getLastName());
657	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
658	        try {
659	            byte[] digest = MessageDigest.getInstance("SHA-256")
660	                .digest((lastNameKey + "|" + postcode).getBytes(StandardCharsets.UTF_8));
661	            StringBuilder hex = new StringBuilder(digest.length * 2);
662	            for (byte b : digest) {
663	                hex.append(String.format("%02x", b));
664	            }
665	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
666	        } catch (NoSuchAlgorithmException ex) {
667	            throw new IllegalStateException("SHA-256 not available", ex);
668	        }
669	    }
670	
671	    /**
672	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
673	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
674	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
675	     * string.
676	     */
677	    private String toHouseholdKey(String value) {
678	        if (value == null) {
679	            return "";
680	        }
681	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
682	    }
683	
684	    /**
685	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
686	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
687	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
688	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
689	     * value, or one that is blank once trimmed, normalizes to an empty string.
690	     *
691	     * @param address the raw address value as submitted, may be {@code null}
692	     * @return the normalized address, or an empty string when none was supplied
693	     */
694	    private String normalizeAddress(String address) {
695	        if (address == null) {
696	            return "";
697	        }
698	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
699	        if (collapsed.isEmpty()) {
700	            return "";
701	        }
702	        String[] tokens = collapsed.split(" ");
703	        StringBuilder normalized = new StringBuilder(collapsed.length());
704	        for (int i = 0; i < tokens.length; i++) {
705	            if (i > 0) {
706	                normalized.append(' ');
707	            }
708	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
709	        }
710	        return normalized.toString();
711	    }
712	
713	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
714	    @Override
715	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
716	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
717	        if (currentOwner == null) {
718	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
719	        }
720	        currentOwner.setAddress(ownerFieldsDto.getAddress());
721	        currentOwner.setCity(ownerFieldsDto.getCity());
722	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
723	        currentOwner.setLastName(ownerFieldsDto.getLastName());
724	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
725	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
726	        this.clinicService.saveOwner(currentOwner);
727	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
728	    }
729	
730	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
731	    @Transactional
732	    @Override
733	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
734	        Owner owner = this.clinicService.findOwnerById(ownerId);
735	        if (owner == null) {
736	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
737	        }
738	        this.clinicService.deleteOwner(owner);
739	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
740	    }
741	
742	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
743	    @Override
744	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
745	        Owner owner = this.clinicService.findOwnerById(ownerId);
746	        if (owner == null) {
747	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
748	        }
749	        HttpHeaders headers = new HttpHeaders();
750	        Pet pet = petMapper.toPet(petFieldsDto);
751	        owner.setId(ownerId);
752	        pet.setOwner(owner);
753	        pet.getType().setName(null);
754	        this.clinicService.savePet(pet);
755	        PetDto petDto = petMapper.toPetDto(pet);
756	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
757	            .buildAndExpand(pet.getId()).toUri());
758	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
759	    }
760	
761	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
762	    @Override
763	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
764	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
765	        if (currentOwner != null) {
766	            Pet currentPet = this.clinicService.findPetById(petId);
767	            if (currentPet != null) {
768	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
769	                currentPet.setName(petFieldsDto.getName());
770	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
771	                this.clinicService.savePet(currentPet);
772	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
773	            }
774	        }
775	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
776	    }
777	
778	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
779	    @Override
780	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
781	        HttpHeaders headers = new HttpHeaders();
782	        Visit visit = visitMapper.toVisit(visitFieldsDto);
783	        Pet pet = new Pet();
784	        pet.setId(petId);
785	        visit.setPet(pet);
786	        this.clinicService.saveVisit(visit);
787	        VisitDto visitDto = visitMapper.toVisitDto(visit);
788	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
789	            .buildAndExpand(visit.getId()).toUri());
790	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
791	    }
792	
793	
794	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
795	    @Override
796	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
797	        Owner owner = this.clinicService.findOwnerById(ownerId);
798	        if (owner != null) {
799	            Pet pet = owner.getPet(petId);
800	            if (pet != null) {
801	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
802	            }
803	        }
804	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
805	    }
